package dev.umbral.test;

import dev.umbral.UmbralContent;
import dev.umbral.block.*;
import dev.umbral.filter.*;
import dev.umbral.filter.FilterProtocol.*;
import dev.umbral.access.*;
import dev.umbral.installation.*;
import dev.umbral.network.*;
import net.fabricmc.fabric.api.event.player.PlayerBlockBreakEvents;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.server.level.*;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.*;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;
import net.minecraft.world.level.storage.TagValueInput;
import net.minecraft.world.phys.*;
import java.util.*;

public final class FilterGameTests {
    static final String STRUCTURE="umbral-test:network";
    static final BlockPos CORE=new BlockPos(1,1,1),NODE=new BlockPos(3,1,1),FILTER=new BlockPos(4,1,4),DOOR=new BlockPos(5,1,6),READER=new BlockPos(6,1,5);
    record Setup(ServerPlayer owner,ServerPlayer visitor,DeviceBlockEntity core,DeviceBlockEntity filter,DeviceBlockEntity door,DeviceBlockEntity reader){}
    DeviceBlockEntity put(GameTestHelper t,BlockPos pos,DeviceBlock block,ServerPlayer p){t.setBlock(pos,block);var d=t.getBlockEntity(pos,DeviceBlockEntity.class);d.initializeOwner(p.getUUID(),"");return d;}
    Setup setup(GameTestHelper t){
        for(int x=0;x<10;x++)for(int z=0;z<10;z++)t.setBlock(new BlockPos(x,0,z),Blocks.STONE);
        var p=(ServerPlayer)t.makeMockServerPlayer(GameType.SURVIVAL);var guest=(ServerPlayer)t.makeMockServerPlayer(GameType.SURVIVAL);
        var core=put(t,CORE,UmbralContent.CORE,p);t.setBlock(new BlockPos(2,1,1),UmbralContent.CABLE);var node=put(t,NODE,UmbralContent.NODE,p);node.bind(p.getUUID(),core);
        p.setYRot(0);p.setPos(Vec3.atLowerCornerOf(t.absolutePos(FILTER)).add(.5,0,-1));p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(UmbralContent.FILTER,2));var floor=t.absolutePos(FILTER.below());
        UmbralContent.FILTER.asItem().useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(floor).add(0,.5,0),Direction.UP,floor,false)));
        var filter=t.getBlockEntity(FILTER,DeviceBlockEntity.class);t.assertTrue(FilterBlock.complete(filter),"One real kit builds all seven owned parts");t.assertTrue(p.getMainHandItem().getCount()==1,"Assembly consumes exactly one kit");filter.bind(p.getUUID(),core);filter.filter().rule("minecraft:tnt",1);
        var door=put(t,DOOR,UmbralContent.DOOR,p);t.setBlock(DOOR.above(),UmbralContent.DOOR.defaultBlockState().setValue(SecurityDoorBlock.HALF,DoubleBlockHalf.UPPER));door.bind(p.getUUID(),core);var reader=put(t,READER,UmbralContent.READER,p);reader.bind(p.getUUID(),core);reader.targetDoor(p.getUUID(),door);
        guest.setPos(Vec3.atLowerCornerOf(t.absolutePos(FILTER.relative(Direction.EAST))).add(.5,0,.5));return new Setup(p,guest,core,filter,door,reader);
    }
    Request request(Setup i,Operation op,String selector,int value,UUID who){return new Request(i.filter.getBlockPos(),i.filter.identity(),i.filter.link(),i.filter.getBlockPos(),i.filter.identity(),123,i.filter.filter().revision(),op,selector,value,who);}
    void access(GameTestHelper t,Setup i){t.assertTrue(FilterService.link(i.owner,i.filter,i.door.asDoorTarget()).equals("door_linked"),"Aligned door binds");t.assertTrue(FilterService.mode(i.filter,FilterState.Mode.ACCESS).equals("mode_saved"),"Access mode selects");t.assertTrue(FilterService.arm(i.filter,true).equals("armed"),"Complete online filter arms");}
    ItemStack pass(GameTestHelper t,Setup i){i.owner.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(UmbralContent.ACCESS_CARD));t.assertTrue(AccessService.issue(i.owner,i.reader)==AccessService.Result.ISSUED,"Physical pass issues");for(int n=0;n<36;n++){var item=i.owner.getInventory().getItem(n);if(item.has(UmbralContent.CARD_ID))return item.copy();}throw new AssertionError("Missing issued pass");}
    @GameTest(structure=STRUCTURE) public void realFrameHasAirAndOneDirectoryEntry(GameTestHelper t){var i=setup(t);for(var part:FilterBlock.Part.values()){var pos=FilterBlock.partPos(i.filter.getBlockPos(),Direction.NORTH,part);var d=(DeviceBlockEntity)t.getLevel().getBlockEntity(pos);t.assertTrue(d.ownedBy(i.owner.getUUID()),"Every part owned");t.assertTrue(SecurityDoorBlock.device(t.getLevel(),pos)==i.filter,"Every part resolves to controller");}t.assertTrue(t.getBlockState(FILTER.east()).isAir()&&t.getBlockState(FILTER.east().above()).isAir(),"Passage is actual air");t.assertTrue(InstallationDirectory.get(t.getLevel()).entries(i.owner.getUUID(),i.core.link()).stream().filter(e->e.kind()==DeviceKind.FILTER).count()==1,"No proxy pollution");t.succeed();}
    @GameTest(structure=STRUCTURE) public void radioAndBaseOnlyCable(GameTestHelper t){var i=setup(t);t.assertTrue(NetworkService.inspect(t.getLevel(),i.filter).online(),"Local radio works");t.setBlock(FILTER.west(),UmbralContent.CABLE.defaultBlockState().setValue(CopperCableBlock.CONNECTIONS.get(Direction.EAST),true));t.getLevel().getBlockState(t.absolutePos(FILTER.west())).updateNeighbourShapes(t.getLevel(),t.absolutePos(FILTER.west()),Block.UPDATE_ALL);t.assertTrue(t.getBlockState(FILTER.west()).getValue(CopperCableBlock.CONNECTIONS.get(Direction.EAST)),"Cable meets root");t.setBlock(FILTER.west().above(),UmbralContent.CABLE);t.assertFalse(t.getBlockState(FILTER.west().above()).getValue(CopperCableBlock.CONNECTIONS.get(Direction.EAST)),"Proxy cannot be a port");t.succeed();}
    @GameTest(structure=STRUCTURE) public void inventoryOffhandArmorAndCounts(GameTestHelper t){var i=setup(t);i.visitor.getInventory().setItem(0,new ItemStack(Items.TNT,2));i.visitor.setItemSlot(EquipmentSlot.OFFHAND,new ItemStack(Items.TNT,3));i.visitor.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.TNT,1));var r=FilterInventory.inspect(i.visitor,i.filter.filter().rules());t.assertTrue(r.matches().getFirst().count()==6,"Main hand counted once, offhand and armor included");t.assertTrue(i.visitor.getInventory().getItem(0).getCount()==2&&i.visitor.getOffhandItem().getCount()==3,"No confiscation");t.succeed();}
    @GameTest(structure=STRUCTURE) public void nestedShulkerAndBundleContents(GameTestHelper t){var i=setup(t);var shulker=new ItemStack(Items.SHULKER_BOX);shulker.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(new ItemStack(Items.TNT,5))));var bundle=new ItemStack(Items.BUNDLE);bundle.set(DataComponents.BUNDLE_CONTENTS,BundleContents.EMPTY.copyWithContents(java.util.stream.Stream.of(new ItemStack(Items.TNT,2))));i.visitor.getInventory().setItem(0,shulker);i.visitor.getInventory().setItem(1,bundle);var r=FilterInventory.inspect(i.visitor,i.filter.filter().rules());t.assertTrue(r.matches().getFirst().count()==7,"Carried vanilla contents count");t.assertTrue(shulker.get(DataComponents.CONTAINER).nonEmptyItemCopyStream().findFirst().orElseThrow().getCount()==5,"Containers not changed");t.succeed();}
    @GameTest(structure=STRUCTURE) public void tooDeepInventoryFailsClosed(GameTestHelper t){var i=setup(t);ItemStack next=new ItemStack(Items.TNT);for(int n=0;n<10;n++){var box=new ItemStack(Items.SHULKER_BOX);box.set(DataComponents.CONTAINER,ItemContainerContents.fromItems(List.of(next)));next=box;}i.visitor.getInventory().setItem(0,next);t.assertTrue(FilterInventory.inspect(i.visitor,i.filter.filter().rules()).outcome()==Inspection.Outcome.TOO_COMPLEX,"Bounded traversal denies hidden contents");access(t,i);t.assertTrue(FilterService.checkDoor(i.visitor,i.door)==FilterService.Gate.BLOCKED,"Complex inventory cannot open");t.succeed();}
    @GameTest(structure=STRUCTURE) public void tagsAndPerRuleExceptions(GameTestHelper t){var i=setup(t);t.assertTrue(i.filter.filter().rule("#minecraft:swords",1).equals("rule_saved"),"Real registry tag accepted");i.visitor.getInventory().setItem(0,new ItemStack(Items.IRON_SWORD));t.assertFalse(FilterInventory.inspect(i.visitor,i.filter.filter().rules()).accepted(),"Sword tag matches");i.filter.filter().exempt("#minecraft:swords",i.visitor.getUUID(),"Invitado");t.assertTrue(FilterInventory.inspect(i.visitor,i.filter.filter().rules()).accepted(),"Rule-specific UUID exemption");i.visitor.getInventory().setItem(1,new ItemStack(Items.TNT));t.assertFalse(FilterInventory.inspect(i.visitor,i.filter.filter().rules()).accepted(),"Other restrictions remain");t.succeed();}
    @GameTest(structure=STRUCTURE) public void ownerExemptAndTestStillDetects(GameTestHelper t){var i=setup(t);i.owner.getInventory().setItem(2,new ItemStack(Items.TNT));t.assertTrue(FilterService.inspect(i.filter,i.owner,false).outcome()==Inspection.Outcome.EXEMPT,"Owner can service installation");var s=FilterProtocol.handle(i.owner,request(i,Operation.TEST,"",0,null));t.assertTrue(s.history().getFirst().test()&&s.history().getFirst().outcome()==Inspection.Outcome.MATCH,"Test bypasses owner exemption");t.assertTrue(NexoJournal.get(t.getLevel()).events(i.owner.getUUID(),i.core.link()).stream().noneMatch(e->e.code().startsWith("inspection")),"Tests never generate installation alarms");t.succeed();}
    @GameTest(structure=STRUCTURE) public void accessRequiresValidPassAndFreshInventory(GameTestHelper t){var i=setup(t);access(t,i);var card=pass(t,i);t.assertTrue(AccessService.present(i.visitor,i.reader,new ItemStack(UmbralContent.ACCESS_CARD))==AccessService.Result.DENIED,"Inspection cannot replace a valid pass");i.visitor.getInventory().setItem(1,new ItemStack(Items.TNT,3));t.assertTrue(AccessService.present(i.visitor,i.reader,card)==AccessService.Result.SCAN_BLOCKED,"Restricted pass holder denied");t.assertFalse(i.door.getBlockState().getValue(SecurityDoorBlock.OPEN),"Denied request leaves door closed");i.visitor.getInventory().setItem(1,ItemStack.EMPTY);t.assertTrue(AccessService.present(i.visitor,i.reader,card)==AccessService.Result.GRANTED,"Clear inspected pass holder enters");i.visitor.setPos(i.visitor.position().add(0,0,1));i.visitor.getInventory().setItem(1,new ItemStack(Items.TNT));t.assertTrue(AccessService.present(i.visitor,i.reader,card)==AccessService.Result.SCAN_BLOCKED,"Approval cannot conceal a subsequent item swap");t.succeed();}
    @GameTest(structure=STRUCTURE) public void scanMustBeLocalAndApprovalExpires(GameTestHelper t){var i=setup(t);access(t,i);i.visitor.setPos(i.visitor.position().add(0,0,3));t.assertTrue(FilterService.checkDoor(i.visitor,i.door)==FilterService.Gate.REQUIRED,"No remote free approval");t.succeed();}
    @GameTest(structure=STRUCTURE) public void outageAndReplacementCannotRemoveGuard(GameTestHelper t){var i=setup(t);access(t,i);t.setBlock(CORE,Blocks.AIR);t.assertTrue(FilterService.checkDoor(i.visitor,i.door)==FilterService.Gate.UNAVAILABLE,"Signal loss fails closed");t.assertTrue(i.filter.filter().armed()&&i.door.filterGuard()!=null,"Outage does not silently disarm");t.setBlock(FILTER,Blocks.AIR);t.assertTrue(FilterService.checkDoor(i.visitor,i.door)==FilterService.Gate.UNAVAILABLE,"Destroyed scanner fails closed");t.assertTrue(AccessService.mayOpenManually(i.owner,i.door),"Owner recovery remains");i.visitor.setPos(Vec3.atCenterOf(i.door.getBlockPos()).add(0,0,1));t.assertTrue(AccessService.mayOpenManually(i.visitor,i.door),"Emergency interior exit remains");t.succeed();}
    @GameTest(structure=STRUCTURE) public void explicitDisarmAndReaderRecoveryReleaseGuard(GameTestHelper t){var i=setup(t);access(t,i);t.assertTrue(FilterService.arm(i.filter,false).equals("disarmed")&&i.door.filterGuard()==null,"Explicit disarm releases extra condition");FilterService.arm(i.filter,true);t.setBlock(FILTER,Blocks.AIR);i.owner.setPos(Vec3.atCenterOf(i.reader.getBlockPos()));var result=AccessProtocol.handle(i.owner,new AccessProtocol.Request(i.reader.getBlockPos(),i.reader.identity(),i.reader.link(),1,AccessProtocol.Operation.CLEAR_FILTER,null));t.assertTrue(result.result()==AccessService.Result.FILTER_CLEARED&&!result.filtered(),"Reader recovers destroyed scanner");t.succeed();}
    @GameTest(structure=STRUCTURE) public void allFramePartsRejectForeignBreaking(GameTestHelper t){var i=setup(t);for(var part:FilterBlock.Part.values()){var pos=FilterBlock.partPos(i.filter.getBlockPos(),Direction.NORTH,part);t.assertFalse(PlayerBlockBreakEvents.BEFORE.invoker().beforeBlockBreak(t.getLevel(),i.visitor,pos,t.getLevel().getBlockState(pos),t.getLevel().getBlockEntity(pos)),"No foreign breaking: "+part);}t.succeed();}
    @GameTest(structure=STRUCTURE) public void breakTopReturnsExactlyOneKit(GameTestHelper t){var i=setup(t);t.getLevel().destroyBlock(i.filter.getBlockPos().above(2),true);t.runAfterDelay(2,()->{int total=t.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(i.filter.getBlockPos()).inflate(4),e->e.getItem().is(UmbralContent.FILTER.asItem())).stream().mapToInt(e->e.getItem().getCount()).sum();t.assertTrue(total==1,"Any part dismantles frame into exactly one kit, got "+total);for(var part:FilterBlock.Part.values())t.assertFalse(t.getLevel().getBlockState(FilterBlock.partPos(i.filter.getBlockPos(),Direction.NORTH,part)).is(UmbralContent.FILTER),"No orphan frame");t.succeed();});}
    @GameTest(structure=STRUCTURE) public void occupiedOpeningDoesNotPartiallyPlace(GameTestHelper t){var i=setup(t);var root=new BlockPos(1,1,7);t.setBlock(root.east().above(),Blocks.STONE);i.owner.setYRot(0);var kit=new ItemStack(UmbralContent.FILTER);i.owner.setItemInHand(InteractionHand.MAIN_HAND,kit);var floor=t.absolutePos(root.below());UmbralContent.FILTER.asItem().useOn(new UseOnContext(i.owner,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(floor).add(0,.5,0),Direction.UP,floor,false)));t.assertTrue(kit.getCount()==1&&t.getBlockState(root).isAir(),"Obstruction preserves kit and entire footprint");t.succeed();}
    @GameTest(structure=STRUCTURE) public void staleAndForeignEditingCannotChangeRules(GameTestHelper t){var i=setup(t);var r=request(i,Operation.RULE,"minecraft:lava_bucket",2,null);var foreign=FilterProtocol.handle(i.visitor,r);t.assertFalse(foreign.valid(),"Visitor has no private settings");t.assertTrue(FilterProtocol.handle(i.owner,r).result().equals("rule_saved"),"Owner edits");t.assertTrue(FilterProtocol.handle(i.owner,r).result().equals("stale"),"Old revision rejected");t.assertTrue(i.filter.filter().rules().size()==2,"Rejected edit does not mutate");t.succeed();}
    @GameTest(structure=STRUCTURE) public void arbitraryInventorySlotAndExceptionUUIDAreRejected(GameTestHelper t){var i=setup(t);t.assertTrue(FilterProtocol.handle(i.owner,request(i,Operation.RULE,"",-100,null)).result().equals("bad_rule"),"Slot bounds checked");t.assertTrue(FilterProtocol.handle(i.owner,request(i,Operation.EXEMPT,"minecraft:tnt",0,UUID.randomUUID())).result().equals("unknown_player"),"No forged exception profiles");t.assertTrue(FilterProtocol.handle(i.owner,request(i,Operation.RULE,"#minecraft:nonexistent",1,null)).result().equals("bad_rule"),"Unknown registry tags rejected");t.succeed();}
    @GameTest(structure=STRUCTURE) public void remoteOwnerMayEditOnlyFromOnlineConsole(GameTestHelper t){var i=setup(t);i.owner.setPos(Vec3.atCenterOf(i.core.getBlockPos()));var r=new Request(i.core.getBlockPos(),i.core.identity(),i.core.link(),i.filter.getBlockPos(),i.filter.identity(),10,i.filter.filter().revision(),Operation.RULE,"minecraft:lava_bucket",1,null);t.assertTrue(FilterProtocol.handle(i.owner,r).result().equals("rule_saved"),"Core manages online scanner");t.setBlock(CORE,Blocks.AIR);t.assertFalse(FilterProtocol.handle(i.owner,new Request(r.root(),r.identity(),r.link(),r.target(),r.targetIdentity(),11,i.filter.filter().revision(),Operation.QUERY,"",0,null)).valid(),"Disconnected remote scanner cannot be edited");t.succeed();}
    @GameTest(structure=STRUCTURE) public void modeChangesKeepPassRequirementAndReleaseGuard(GameTestHelper t){var i=setup(t);access(t,i);FilterService.mode(i.filter,FilterState.Mode.INFORM);t.assertTrue(i.door.filterGuard()==null,"Inform removes additional door condition");i.visitor.getInventory().setItem(1,new ItemStack(Items.TNT));t.assertTrue(FilterService.checkDoor(i.visitor,i.door)==FilterService.Gate.ALLOW,"Inform never gates");t.assertTrue(AccessService.present(i.visitor,i.reader,new ItemStack(UmbralContent.ACCESS_CARD))==AccessService.Result.DENIED,"Valid pass still required");t.succeed();}
    @GameTest(structure=STRUCTURE) public void doorAlignmentAndFacingAreExplained(GameTestHelper t){var i=setup(t);t.assertTrue(FilterService.link(i.owner,i.filter,i.door.asDoorTarget()).equals("door_linked"),"Correct door");t.setBlock(DOOR,i.door.getBlockState().setValue(DeviceBlock.FACING,Direction.SOUTH));t.assertTrue(FilterService.link(i.owner,i.filter,i.door.asDoorTarget()).equals("door_facing"),"Reversed door rejected");t.succeed();}
    @GameTest(structure=STRUCTURE) public void privatePersistenceAndSafePublicTag(GameTestHelper t){var i=setup(t);access(t,i);i.filter.filter().exempt("minecraft:tnt",i.visitor.getUUID(),"Invitado");FilterService.report(i.filter,i.visitor,FilterService.inspect(i.filter,i.visitor,true),true);var saved=i.filter.saveWithoutMetadata(t.getLevel().registryAccess());var restored=new DeviceBlockEntity(i.filter.getBlockPos(),i.filter.getBlockState());restored.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,t.getLevel().registryAccess(),saved));t.assertTrue(restored.filter().rules().equals(i.filter.filter().rules())&&restored.filter().armed()&&restored.filter().door().equals(i.door.asDoorTarget())&&restored.filter().history().size()==1,"Rules exceptions door mode and bounded history persist");String publicTag=i.filter.getUpdateTag(t.getLevel().registryAccess()).toString();t.assertFalse(publicTag.contains("exemptions")||publicTag.contains("minecraft:tnt")||publicTag.contains("Invitado"),"Public render packet never leaks rules or inventory");t.succeed();}
    @GameTest(structure=STRUCTURE) public void nexoReceivesActualItemCountAndPlayer(GameTestHelper t){var i=setup(t);i.visitor.getInventory().setItem(0,new ItemStack(Items.TNT,7));FilterService.report(i.filter,i.visitor,FilterService.inspect(i.filter,i.visitor,false),false);var events=NexoJournal.get(t.getLevel()).events(i.owner.getUUID(),i.core.link());var e=events.getFirst();t.assertTrue(e.code().equals("inspection_match")&&e.item().equals("minecraft:tnt")&&e.amount()==7&&e.subject().equals(i.visitor.getGameProfile().name()),"Journal shows facts, not a generic alarm");t.succeed();}
    @GameTest(structure=STRUCTURE) public void rulesHaveFirmLimits(GameTestHelper t){var i=setup(t);var s=i.filter.filter();for(var item:List.of(Items.STONE,Items.DIRT,Items.COBBLESTONE,Items.SAND,Items.GRAVEL,Items.GLASS,Items.IRON_INGOT,Items.GOLD_INGOT,Items.COPPER_INGOT,Items.DIAMOND,Items.REDSTONE,Items.COAL,Items.CHARCOAL,Items.STICK,Items.APPLE))s.rule(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item).toString(),1);t.assertTrue(s.rules().size()==16&&s.rule("minecraft:lava_bucket",1).equals("full"),"16-rule cap");for(int n=0;n<16;n++)s.exempt("minecraft:tnt",UUID.randomUUID(),"Guest"+n);t.assertTrue(s.exempt("minecraft:tnt",UUID.randomUUID(),"Overflow").equals("full"),"16-exemption cap");t.succeed();}

    @GameTest(structure=STRUCTURE,maxTicks=100) public void liveCrossingPulsesAndDoesNotSpam(GameTestHelper t){var i=setup(t);var live=t.makeMockServerPlayerInLevel();live.setPos(i.visitor.position());live.getInventory().setItem(0,new ItemStack(Items.TNT,3));FilterService.mode(i.filter,FilterState.Mode.ALARM);FilterService.arm(i.filter,true);t.runAfterDelay(10,()->{t.assertTrue(i.filter.filter().history().size()==1,"Actual crossing records one visit");t.assertTrue(t.getLevel().getSignal(i.filter.getBlockPos(),Direction.NORTH)==15,"Alarm supplies redstone");t.runAfterDelay(45,()->{t.assertTrue(i.filter.filter().history().size()==1,"Idle visitor never spams notices");t.assertTrue(t.getLevel().getSignal(i.filter.getBlockPos(),Direction.NORTH)==0,"Pulse expires without retriggering");t.getLevel().getServer().getPlayerList().remove(live);t.succeed();});});}
    @GameTest(structure=STRUCTURE,maxTicks=300) public void approvalsExpireAfterTenSeconds(GameTestHelper t){var i=setup(t);access(t,i);t.assertTrue(FilterService.checkDoor(i.visitor,i.door)==FilterService.Gate.ALLOW,"Passage grants inspection");i.visitor.setPos(i.visitor.position().add(0,0,3));t.runAfterDelay(205,()->{t.assertTrue(FilterService.checkDoor(i.visitor,i.door)==FilterService.Gate.REQUIRED,"Old approval expires");t.succeed();});}

    @GameTest(structure=STRUCTURE) public void oldExceptionsStayRemovableBeyondProfilePageLimit(GameTestHelper t){var i=setup(t);var s=i.filter.filter();UUID last=null;String selector="";for(var item:List.of(Items.STONE,Items.DIRT,Items.SAND,Items.GRAVEL,Items.GLASS)){selector=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item).toString();s.rule(selector,1);for(int n=0;n<16;n++){last=UUID.randomUUID();s.exempt(selector,last,"Historical"+n);}}t.assertTrue(FilterProtocol.profiles(i.owner,i.filter).size()==64,"Public profile list stays bounded");t.assertTrue(FilterProtocol.handle(i.owner,request(i,Operation.EXEMPT,selector,0,last)).result().equals("exception_saved"),"An older saved exception can always be removed");t.succeed();}
}
